'use client';

import Link from 'next/link';
import { Minus, Plus, Trash2 } from 'lucide-react';
import { useCart } from '@/features/cart/CartContext';
import { Drawer } from '@ik/ui';
import { Button } from '@ik/ui';
import { formatPrice } from '@ik/utils';
import { ROUTES } from '@ik/config';

export function CartDrawer() {
  const { drawerOpen, closeDrawer, items, totals, setQuantity, remove } = useCart();

  return (
    <Drawer open={drawerOpen} onClose={closeDrawer} side="right" title="Your cart">
      {items.length === 0 ? (
        <div className="flex flex-col items-center justify-center h-full text-center gap-4 p-8">
          <p className="font-display text-[1.5rem] text-ink">Your cart is quiet.</p>
          <p className="text-[0.9375rem] text-muted max-w-[280px]">
            Browse the winter edit and add something to your cart.
          </p>
          <Button as="link" href={ROUTES.SHOP} onClick={closeDrawer}>
            Enter the shop
          </Button>
        </div>
      ) : (
        <div className="flex flex-col h-full">
          <ul className="flex-1 divide-y divide-ink-100">
            {items.map((it) => (
              <li key={it.id} className="flex gap-4 p-6">
                <Link href={ROUTES.PRODUCT(it.snapshot.slug)} onClick={closeDrawer} className="w-20 h-24 bg-frame rounded-md overflow-hidden shrink-0">
                  {/* eslint-disable-next-line @next/next/no-img-element */}
                  <img src={it.snapshot.image.src} alt={it.snapshot.image.alt} className="w-full h-full object-cover" />
                </Link>
                <div className="flex-1 flex flex-col gap-2 min-w-0">
                  <Link href={ROUTES.PRODUCT(it.snapshot.slug)} onClick={closeDrawer} className="font-display text-[1.0625rem] text-ink hover:text-vermilion transition-colors truncate">
                    {it.snapshot.title}
                  </Link>
                  <p className="text-[0.75rem] text-muted">{it.snapshot.optionLabel}</p>
                  <div className="flex items-center gap-3 mt-1">
                    <div className="inline-flex items-center border border-ink-300 rounded-md">
                      <button type="button" aria-label="Decrease" onClick={() => setQuantity(it.id, it.quantity - 1)} className="w-8 h-8 inline-flex items-center justify-center text-ink hover:bg-frame">
                        <Minus size={14} strokeWidth={1.25} />
                      </button>
                      <span className="w-8 text-center text-[0.875rem] tabular-nums">{it.quantity}</span>
                      <button type="button" aria-label="Increase" onClick={() => setQuantity(it.id, it.quantity + 1)} className="w-8 h-8 inline-flex items-center justify-center text-ink hover:bg-frame">
                        <Plus size={14} strokeWidth={1.25} />
                      </button>
                    </div>
                    <button type="button" onClick={() => remove(it.id)} aria-label="Remove" className="text-muted hover:text-danger">
                      <Trash2 size={16} strokeWidth={1.25} />
                    </button>
                  </div>
                </div>
                <p className="text-[0.9375rem] text-ink tabular-nums shrink-0">{formatPrice(it.snapshot.unitPrice * it.quantity)}</p>
              </li>
            ))}
          </ul>

          <div className="border-t border-ink-100 p-6 flex flex-col gap-4">
            <div className="flex justify-between text-[0.9375rem] text-ink">
              <span>Subtotal</span>
              <span className="tabular-nums">{formatPrice(totals.subtotal)}</span>
            </div>
            <p className="text-[0.75rem] text-muted">Shipping and taxes calculated at checkout.</p>
            <Button as="link" href={ROUTES.CHECKOUT} onClick={closeDrawer} fullWidth>
              Proceed to checkout
            </Button>
            <Link href={ROUTES.CART} onClick={closeDrawer} className="text-center text-[0.8125rem] text-muted underline underline-offset-4 hover:text-vermilion">
              View full cart
            </Link>
          </div>
        </div>
      )}
    </Drawer>
  );
}
